Q("سورة الحشر: الآيات 18–24", 23, 0.399, 0.679,
  ["أن يستخلص الطالب الأمر بالتقوى ومحاسبة النفس.", "أن يبين عظمة القرآن.", "أن يتعرف أسماء الله الحسنى الواردة في آخر السورة."],
  "أسأل: ماذا قدمت لغدك؟",
  "يأمر الله المؤمنين بالتقوى، بفعل المأمورات وترك المنهيات، ويحثهم على محاسبة النفس: ولتنظر نفس ما قدمت لغد، ثم يؤكد الأمر بالتقوى لأنه خبير بما يعملون. ويحذرهم من أن يكونوا كالذين نسوا الله فأنساهم أنفسهم، أولئك هم الفاسقون؛ ولا يستوي أصحاب النار وأصحاب الجنة. ثم يبين عظمة القرآن: لو أنزل على جبل لرأيته خاشعا متصدعا من خشية الله. ويختم بذكر أسماء الله الحسنى: هو الله الذي لا إله إلا هو عالم الغيب والشهادة الرحمن الرحيم، الملك القدوس السلام المؤمن المهيمن العزيز الجبار المتكبر، الخالق البارئ المصور، له الأسماء الحسنى.",
  ["التقوى ومحاسبة النفس.", "نسيان الله يورث نسيان النفس.", "لا يستوي أصحاب النار وأصحاب الجنة.", "عظمة القرآن: لو أنزل على جبل لتصدع.", "أسماء الله الحسنى."],
  ("ما معنى «ولتنظر نفس ما قدمت لغد»؟", "لتحاسب كل نفس نفسها على ما ادخرت من عمل صالح ليوم القيامة."),
  ["الأمر بالتقوى مرتين.", "الجزاء من جنس العمل: نسوا الله فأنساهم أنفسهم.", "خشوع الجبل لو أنزل عليه القرآن.", "أسماء الله: الملك، القدوس، السلام، المؤمن، المهيمن…"],
  ["1. محاسبة النفس.", "2. دوام ذكر الله.", "3. تعظيم القرآن والخشوع عند سماعه.", "4. معرفة الله بأسمائه وصفاته."],
  apps=[("اذكر خمسة من أسماء الله الواردة في آخر سورة الحشر.", "الملك، القدوس، السلام، المؤمن، المهيمن."), ("ما جزاء من نسي الله؟", "أنساه الله نفسه، وهو من الفاسقين.")]),
