  [S("المنطلق", ["حديث: اعرف وكاءها وعفاصها ثم عرفها سنة…", "حديث جابر: رخص في العصا والسوط والحبل.", "ضالة الإبل: مالك ولها؟ معها سقاؤها وحذاؤها."]),
   S("حالات اللقطة", table=[["الحالة", "مثال", "الحكم"], ["ما لا تتبعه همة الناس", "السوط، الرغيف، التمرة", "يملكه آخذه بلا تعريف"], ["ما يمتنع من صغار السباع", "الإبل", "لا يجوز التقاطه"], ["سائر الأموال", "الذهب، الفضة، المتاع", "يعرّف سنة ثم يستنفق ويضمن"]])],
