  [S("المنطلق", ["آية الدين: «فرهان مقبوضة» (البقرة).", "توفي رسول الله ﷺ ودرعه مرهونة عند يهودي بثلاثين صاعا من شعير."]),
   S("التعريف والحكم", ["لغة: الثبوت والدوام ؛ اصطلاحا: توثقة دين بعين.", "جائز سفرا وحضرا باتفاق المذاهب الأربعة."]),
   S("الأركان", ["الراهن، المرتهن، المرهون، المرهون به، الصيغة."])],
